#!/usr/bin/env bash
# benchmarks/queue/T_CRIU2_convergence_mmap.sh
# Generated by Antigravity for BENCH_08 (Python Sanitized Version)

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
source "${REPO_ROOT}/config/hardware.env"

# Tool Paths
CUDA_CHECKPOINT="/usr/local/bin/cuda-checkpoint"
CRIU="/usr/sbin/criu"
LLAMA_SERVER="${IK_LLAMA_BUILD_DIR}/bin/llama-server"

# Configuration
CKPT_DIR="${REPO_ROOT}/checkpoints/convergence_mmap"
rm -rf "${CKPT_DIR}" && mkdir -p "${CKPT_DIR}"
TIMESTAMP=$(date -u +%Y%m%dT%H%M%SZ)
RESULTS_DIR="${REPO_ROOT}/results/T_CRIU2_mmap_${TIMESTAMP}"
mkdir -p "${RESULTS_DIR}"

# Model path on host
MODEL_PATH="${MODEL_CACHE}/${CONVERGENCE_MODEL}"

PROMPT="List the three laws of thermodynamics in one sentence each."

echo "--- Step 0: Cleanup ---"
CONV_CONTAINER=$(podman ps --format "{{.Names}}" | grep -i "convergence\|ikllamacpp" | head -1 || true)
if [ -n "${CONV_CONTAINER}" ]; then
    podman stop "${CONV_CONTAINER}" && podman rm "${CONV_CONTAINER}"
    sleep 3
fi
sudo killall llama-server 2>/dev/null || true

# --- Start llama-server with Python Sanitization ---
echo "--- Step 1: Starting llama-server on Host (Python Sanitized) ---"
export LD_LIBRARY_PATH="${IK_LLAMA_BUILD_DIR}/src:${IK_LLAMA_BUILD_DIR}/ggml/src:${IK_LLAMA_BUILD_DIR}/examples/mtmd:/usr/local/cuda/targets/x86_64-linux/lib"

# We use Python to launch the process with a clean session and closed FDs
# This prevents the 'session ID' and 'dirty FD' errors in CRIU
python3 -c "
import subprocess, os
log = open('${RESULTS_DIR}/llama_server.log', 'w')
env = os.environ.copy()
subprocess.Popen(
    ['${LLAMA_SERVER}', 
     '--model', '${MODEL_PATH}', 
     '--port', '8002', 
     '--host', '127.0.0.1', 
     '-ngl', '50', 
     '--cpu-moe', 
     '-t', '32', '-np', '1', '-c', '4096', '--jinja'],
    stdout=log, stderr=log, stdin=subprocess.DEVNULL,
    env=env, close_fds=True, start_new_session=True
)
"
sleep 5
MAIN_PID=$(pgrep -f "llama-server.*--port 8002" | head -1)
echo "llama-server (mmap) started with Host PID: ${MAIN_PID}"

# --- DIAGNOSTIC ---
echo "--- DIAGNOSTIC: Sanitized FDs ---"
sudo ls -l "/proc/${MAIN_PID}/fd" || echo "Process gone?"
# ------------------

# Wait for healthy
echo "Waiting for health check..."
for i in $(seq 1 120); do
    if curl -sf http://localhost:8002/health > /dev/null 2>&1; then
        echo "HEALTH OK"
        break
    fi
    sleep 1
done

# --- Baseline inference ---
echo "Recording baseline (mmap warm) response..."
START_MS=$(date +%s%3N)
PRE_RESPONSE=$(curl -sf http://localhost:8002/v1/completions \
  -H "Content-Type: application/json" \
  -d "{\"model\":\"convergence\",\"prompt\":\"${PROMPT}\",\"max_tokens\":50,\"temperature\":0.0}")
END_MS=$(date +%s%3N)
BASELINE_TTFT_S=$(python3 -c "print(round(($END_MS - $START_MS) / 1000.0, 2))")
echo "Baseline TTFT: ${BASELINE_TTFT_S}s"
echo "${PRE_RESPONSE}" > "${RESULTS_DIR}/pre_checkpoint_response.json"

# --- Checkpoint ---
echo "--- Step 2: Checkpointing ---"
echo "[T_CRIU2] Suspending GPU state for PID ${MAIN_PID}..."
sudo "${CUDA_CHECKPOINT}" --toggle --pid "${MAIN_PID}"

echo "[T_CRIU2] Performing CRIU Dump..."
if ! sudo "${CRIU}" dump \
    --tree "${MAIN_PID}" \
    --images-dir "${CKPT_DIR}" \
    --shell-job \
    --tcp-established \
    --file-locks; then
    echo "ERROR: CRIU Dump failed."
    sudo "${CUDA_CHECKPOINT}" --toggle --pid "${MAIN_PID}" || true
    exit 1
fi

# --- Step 3: Drop page cache ---
echo "Dropping page cache..."
sync && sudo sh -c "echo 3 > /proc/sys/vm/drop_caches"

# --- Restore ---
echo "--- Step 4: Restoring ---"
RESTORE_START_MS=$(date +%s%3N)

echo "[T_CRIU2] Performing CRIU Restore..."
if ! sudo "${CRIU}" restore \
    --images-dir "${CKPT_DIR}" \
    --shell-job \
    --tcp-established \
    --file-locks \
    --restore-detached \
    --ext-mount-map /dev/console:/dev/console; then
    echo "ERROR: CRIU Restore failed."
    exit 1
fi

sudo "${CUDA_CHECKPOINT}" --toggle --pid "${MAIN_PID}" || true
RESTORE_END_MS=$(date +%s%3N)
RESTORE_ELAPSED_S=$(python3 -c "print(round(($RESTORE_END_MS - $RESTORE_START_MS) / 1000.0, 2))")
echo "Restore time: ${RESTORE_ELAPSED_S}s"

# --- Verification ---
for REP in 1 2 3; do
  START_MS=$(date +%s%3N)
  RESPONSE=$(curl -sf http://localhost:8002/v1/completions \
    -H "Content-Type: application/json" \
    -d "{\"model\":\"convergence\",\"prompt\":\"${PROMPT}\",\"max_tokens\":50,\"temperature\":0.0}")
  END_MS=$(date +%s%3N)
  TTFT_S=$(python3 -c "print(round(($END_MS - $START_MS) / 1000.0, 2))")
  echo "Post-restore rep=${REP}: TTFT=${TTFT_S}s"
done

# Cleanup
sudo kill -9 $MAIN_PID 2>/dev/null || true
"${REPO_ROOT}/infra/scripts/deploy.sh" ikllamacpp convergence ""
echo "Benchmark complete."
